<?php
declare(strict_types=1);require dirname(__DIR__).'/src/bootstrap.php';if(PHP_SAPI!=='cli')exit("CLI only\n");
$url=(string)env('ANVISA_CSV_URL');$tmp=sys_get_temp_dir().'/anvisa_medicamentos_'.date('YmdHis').'.csv';$in=fopen($url,'rb');if(!$in)throw new RuntimeException('Falha ao abrir CSV Anvisa');$out=fopen($tmp,'wb');stream_copy_to_stream($in,$out);fclose($in);fclose($out);
$fh=fopen($tmp,'rb');$header=fgetcsv($fh,0,';');if(!$header)throw new RuntimeException('CSV sem cabeçalho');$norm=fn($s)=>preg_replace('/[^A-Z0-9]+/','_',iconv('UTF-8','ASCII//TRANSLIT',mb_strtoupper(trim((string)$s),'UTF-8'))?:mb_strtoupper(trim((string)$s)));
$keys=array_map($norm,$header);$pick=function(array $row,array $names)use($keys,$norm){foreach($names as $n){$i=array_search($norm($n),$keys,true);if($i!==false&&isset($row[$i]))return trim((string)$row[$i]);}return'';};
$run=$db->prepare("INSERT INTO import_runs(source,status) VALUES('ANVISA','running')");$run->execute();$rid=(int)$db->lastInsertId();$seen=0;$written=0;$up=$db->prepare("INSERT INTO medications(registration,product_name,active_ingredient,company,regulatory_category,therapeutic_class,presentation,registration_status,requires_prescription,retain_prescription,controlled,remote_delivery_allowed,review_required,bula_url,source,source_updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'ANVISA',CURRENT_TIMESTAMP) ON CONFLICT(registration) DO UPDATE SET product_name=excluded.product_name,active_ingredient=excluded.active_ingredient,company=excluded.company,regulatory_category=excluded.regulatory_category,therapeutic_class=excluded.therapeutic_class,presentation=excluded.presentation,registration_status=excluded.registration_status,requires_prescription=excluded.requires_prescription,retain_prescription=excluded.retain_prescription,controlled=excluded.controlled,remote_delivery_allowed=excluded.remote_delivery_allowed,bula_url=excluded.bula_url,source_updated_at=CURRENT_TIMESTAMP");
$db->beginTransaction();while(($row=fgetcsv($fh,0,';'))!==false){$seen++;$reg=$pick($row,['NUMERO_REGISTRO_PRODUTO','REGISTRO','NUMERO_REGISTRO']);$name=$pick($row,['NOME_PRODUTO','PRODUTO','NOME_COMERCIAL']);if($reg===''||$name==='')continue;$active=$pick($row,['PRINCIPIO_ATIVO','PRINCIPIO ATIVO']);$company=$pick($row,['EMPRESA_DETENTORA_REGISTRO','EMPRESA','RAZAO_SOCIAL']);$cat=$pick($row,['CATEGORIA_REGULATORIA','CATEGORIA']);$class=$pick($row,['CLASSE_TERAPEUTICA','CLASSE']);$pres=$pick($row,['APRESENTACAO','APRESENTACAO_PRODUTO']);$status=$pick($row,['SITUACAO_REGISTRO','SITUACAO']);[$rx,$retain,$controlled,$remote,$review]=Catalog::classify($cat,$class,$pres);$up->execute([$reg,$name,$active,$company,$cat,$class,$pres,$status,$rx,$retain,$controlled,$remote,$review,env('BULARIO_URL','https://consultas.anvisa.gov.br/#/bulario/')]);$written++;if($written%1000===0){$db->commit();$db->beginTransaction();echo "Importados $written\n";}}
$db->commit();fclose($fh);@unlink($tmp);$done=$db->prepare("UPDATE import_runs SET status='done',rows_seen=?,rows_written=?,finished_at=CURRENT_TIMESTAMP WHERE id=?");$done->execute([$seen,$written,$rid]);echo "ANVISA_OK seen=$seen written=$written\n";
